// Extrai IDs de vagas do email de alerta do LinkedIn (um email traz várias vagas)
const out = [];
for (const item of $input.all()) {
  const html = item.json.html || item.json.textHtml || item.json.text || '';
  const ids = [...new Set([...html.matchAll(/jobs\/view\/(\d{6,})/g)].map(m => m[1]))];
  for (const id of ids) {
    out.push({ json: { jobId: id, link: `https://www.linkedin.com/jobs/view/${id}`, emailSubject: item.json.subject } });
  }
}
return out;

// Prepara o pedido ao Claude com o Perfil-mestre v6 e as regras do projeto
// v2: prompt caching (a parte fixa vai em 'system' e é guardada em cache) + só o bloco da descrição da vaga (sem menus/rodapés do LinkedIn), completo
const REGRAS = `[REMOVED: project rules - see prompts/project-system-prompt.md for the public version]`;

const PERFIL = `[REMOVED: private master profile - see knowledge-base/master-profile.example.md for the public version]`;

// Parte FIXA (igual em todas as vagas): fica em cache e, a partir da 2.ª vaga, custa ~10% do preço normal
const SISTEMA = `És o assistente de candidaturas da Andressa para Data/BI/Analytics.

${REGRAS}

=== PERFIL-MESTRE (única fonte de factos) ===
${PERFIL}`;

const vagas = $('Ignorar vagas já vistas').all();
const out = [];
$input.all().forEach((item, i) => {
  const html = item.json.data || '';
  const pick = re => (html.match(re) || [, ''])[1].replace(/<[^>]+>/g, '').trim();
  const titulo = pick(/<h2[^>]*top-card-layout__title[^>]*>([\s\S]*?)<\/h2>/);
  const empresa = pick(/topcard__org-name-link[^>]*>([\s\S]*?)<\/a>/);
  // Só o bloco escrito pelo recrutador; se não o encontrar, usa a página toda
  const bloco = (html.match(/<div[^>]*show-more-less-html__markup[^>]*>([\s\S]*?)<\/div>\s*<button/) ||
                 html.match(/<div[^>]*description__text[^>]*>([\s\S]*?)<\/section>/) || [, html])[1];
  const criterios = (html.match(/<ul[^>]*description__job-criteria-list[^>]*>([\s\S]*?)<\/ul>/) || [, ''])[1];
  const descricao = (bloco + '\n' + criterios)
    .replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/g, '')
    .replace(/<br\s*\/?>|<\/(p|li|div|h\d)>/g, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ').replace(/&#39;/g, "'").replace(/&quot;/g, '"')
    .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim()
    .slice(0, 20000); // limite de segurança, não corta vagas normais

  const vagaTexto = `=== VAGA: ${titulo} @ ${empresa} ===
${descricao}

TAREFAS
1. Avalia o fit de 0 a 100 com realismo (60 corresponde a cumprir cerca de 60% dos obrigatórios).
2. Lista os requisitos que ela cumpre (com a prova) e as lacunas.
3. Se score >= 60, escreve o CV adaptado (texto simples, pronto a copiar) e a carta.
4. Em para_confirmar, lista o que ficou de fora por estar [POR CONFIRMAR] e seria útil nesta vaga.

Responde APENAS com JSON válido, sem texto antes ou depois:
{"score":0,"recomendacao":"Candidatar | Candidatar com ressalvas | Não vale a pena","resumo":"","cumpre":[],"lacunas":[],"palavras_chave":[],"lingua":"PT ou EN","cv":"","carta":"","para_confirmar":[]}`;

  const v = vagas[i]?.json || {};
  out.push({ json: {
    jobId: v.jobId, link: v.link, titulo, empresa,
    body: {
      model: 'claude-sonnet-5-5',
      max_tokens: 8000, thinking: { type: 'between_tools' },
      system: [{ type: 'text', text: SISTEMA, cache_control: { type: 'ephemeral' } }],
      messages: [{ role: 'user', content: vagaTexto }]
    }
  }});
});
return out;

const out = [];
const vagas = $('Filtro gratuito').all();
$input.all().forEach((item, i) => {
  const txt = (item.json.content || []).map(c => c.text || '').join('');
  let r = {};
  try { r = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1)); }
  catch (e) { r = { score: 0, resumo: 'Erro a ler resposta do Claude', lacunas: [], cumpre: [] }; }
  const v = vagas[i].json;
  out.push({ json: {
    jobId: v.jobId, link: v.link, titulo: v.titulo, empresa: v.empresa,
    score: r.score, resumo: r.resumo,
    cumpre: (r.cumpre || []).join(' · '), lacunas: (r.lacunas || []).join(' · '),
    cv: r.cv || '', carta: r.carta || '', data: new Date().toISOString().slice(0, 10)
  }});
});
return out;

// FILTRO GRATUITO: corre antes do Claude e descarta vagas fora do alvo (não gasta créditos)
const MAX_POR_EXECUCAO = 15; // teto de vagas enviadas ao Claude por execução

const NIVEL_BLOQUEADO = /mid-senior|pleno|s[eê]nior|director|diretor|executive|executivo/i;
const TITULO_BLOQUEADO = /\b(senior|s[eéê]nior|sr\.?|lead|principal|manager|gestor|head|staff|architect|arquiteto)\b/i;
const ANOS_BLOQUEADO = /\b([3-9]|1\d)\s*\+\s*(years|anos)|(at least|minimum( of)?|m[ií]nimo( de)?|pelo menos|mais de)\s*([3-9]|1\d)\s*(years|anos)/i;

const htmls = $('Buscar descrição da vaga').all();
const passam = [];

$input.all().forEach((item, i) => {
  const html = htmls[i]?.json?.data || '';
  const nivelMatch = html.match(/description__job-criteria-text[^>]*>([\s\S]*?)<\/span>/);
  const nivel = nivelMatch ? nivelMatch[1].replace(/<[^>]+>/g, '').trim() : '';
  const texto = html.replace(/<[^>]+>/g, ' ');
  const titulo = item.json.titulo || '';

  let motivo = '';
  if (NIVEL_BLOQUEADO.test(nivel)) motivo = `nível: ${nivel}`;
  else if (TITULO_BLOQUEADO.test(titulo)) motivo = `título: ${titulo}`;
  else if (ANOS_BLOQUEADO.test(texto)) motivo = `anos: ${(texto.match(ANOS_BLOQUEADO) || [''])[0]}`;

  if (motivo) console.log(`Descartada (${motivo}) → ${titulo} @ ${item.json.empresa}`);
  else passam.push({ json: { ...item.json, nivel } });
});

return passam.slice(0, MAX_POR_EXECUCAO);
